CREATE TABLE "User" ("id" UUID NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"emailVerified" BOOLEAN NOT NULL DEFAULT false,"image" TEXT,"marketingEmails" BOOLEAN NOT NULL DEFAULT false,"steamId" TEXT,"steamDisplayName" TEXT,"steamAvatarUrl" TEXT,"steamLastSyncedAt" TIMESTAMP(3),"steamProfileVisibility" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Account" ("id" UUID NOT NULL,"accountId" TEXT NOT NULL,"providerId" TEXT NOT NULL,"userId" UUID NOT NULL,"accessToken" TEXT,"refreshToken" TEXT,"idToken" TEXT,"accessTokenExpiresAt" TIMESTAMP(3),"refreshTokenExpiresAt" TIMESTAMP(3),"scope" TEXT,"password" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Account_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" UUID NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"token" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"ipAddress" TEXT,"userAgent" TEXT,"userId" UUID NOT NULL,CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Verification" ("id" UUID NOT NULL,"identifier" TEXT NOT NULL,"value" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Verification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RateLimit" ("id" UUID NOT NULL,"key" TEXT NOT NULL,"count" INTEGER NOT NULL,"lastRequest" BIGINT NOT NULL,CONSTRAINT "RateLimit_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WishlistItem" ("id" UUID NOT NULL,"userId" UUID NOT NULL,"gameId" UUID NOT NULL,"note" VARCHAR(500),"priceAtAddMinor" INTEGER,"priceCurrency" CHAR(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "WishlistItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PriceAlert" ("id" UUID NOT NULL,"wishlistItemId" UUID NOT NULL,"targetPriceMinor" INTEGER,"currency" CHAR(3) NOT NULL DEFAULT 'CZK',"onHistoricalLow" BOOLEAN NOT NULL DEFAULT false,"dropPercent" INTEGER,"enabled" BOOLEAN NOT NULL DEFAULT true,"cooldownHours" INTEGER NOT NULL DEFAULT 24,"lastTriggeredAt" TIMESTAMP(3),"lastCheckedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PriceAlert_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Notification" ("id" UUID NOT NULL,"userId" UUID NOT NULL,"priceAlertId" UUID,"deduplicationKey" TEXT NOT NULL,"type" TEXT NOT NULL,"title" TEXT NOT NULL,"message" TEXT NOT NULL,"gameId" UUID,"priceMinor" INTEGER,"currency" CHAR(3),"targetPriceMinor" INTEGER,"exchangeRateDate" DATE,"usdPriceMinor" INTEGER,"status" TEXT NOT NULL DEFAULT 'pending',"attempts" INTEGER NOT NULL DEFAULT 0,"lastAttemptAt" TIMESTAMP(3),"sentAt" TIMESTAMP(3),"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Notification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AlertCheckRun" ("id" UUID NOT NULL,"lockKey" TEXT,"status" TEXT NOT NULL,"selected" INTEGER NOT NULL DEFAULT 0,"checked" INTEGER NOT NULL DEFAULT 0,"triggered" INTEGER NOT NULL DEFAULT 0,"failed" INTEGER NOT NULL DEFAULT 0,"errorMessage" TEXT,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),CONSTRAINT "AlertCheckRun_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EmailOutbox" ("id" UUID NOT NULL,"userId" UUID,"notificationId" UUID,"template" TEXT NOT NULL,"recipient" TEXT NOT NULL,"payload" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"attempts" INTEGER NOT NULL DEFAULT 0,"nextAttemptAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastAttemptAt" TIMESTAMP(3),"providerMessageId" TEXT,"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "EmailOutbox_pkey" PRIMARY KEY ("id"));
CREATE TABLE "UserConsent" ("id" UUID NOT NULL,"userId" UUID NOT NULL,"kind" TEXT NOT NULL,"version" TEXT NOT NULL,"granted" BOOLEAN NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "UserConsent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EmailVerificationToken" ("id" UUID NOT NULL,"userId" UUID NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EmailVerificationToken_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PasswordResetToken" ("id" UUID NOT NULL,"userId" UUID NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PasswordResetToken_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "User_email_normalized_key" ON "User"(LOWER("email")); CREATE UNIQUE INDEX "User_steamId_key" ON "User"("steamId"); CREATE INDEX "User_createdAt_idx" ON "User"("createdAt");
CREATE UNIQUE INDEX "Account_providerId_accountId_key" ON "Account"("providerId","accountId"); CREATE INDEX "Account_userId_idx" ON "Account"("userId");
CREATE UNIQUE INDEX "Session_token_key" ON "Session"("token"); CREATE INDEX "Session_userId_idx" ON "Session"("userId"); CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE INDEX "Verification_identifier_idx" ON "Verification"("identifier"); CREATE INDEX "Verification_expiresAt_idx" ON "Verification"("expiresAt"); CREATE UNIQUE INDEX "RateLimit_key_key" ON "RateLimit"("key");
CREATE UNIQUE INDEX "WishlistItem_userId_gameId_key" ON "WishlistItem"("userId","gameId"); CREATE INDEX "WishlistItem_userId_createdAt_idx" ON "WishlistItem"("userId","createdAt" DESC); CREATE INDEX "WishlistItem_gameId_idx" ON "WishlistItem"("gameId");
CREATE UNIQUE INDEX "PriceAlert_wishlistItemId_targetPriceMinor_currency_onHistoricalLow_key" ON "PriceAlert"("wishlistItemId","targetPriceMinor","currency","onHistoricalLow"); CREATE INDEX "PriceAlert_enabled_lastCheckedAt_idx" ON "PriceAlert"("enabled","lastCheckedAt");
CREATE UNIQUE INDEX "Notification_deduplicationKey_key" ON "Notification"("deduplicationKey"); CREATE INDEX "Notification_userId_readAt_createdAt_idx" ON "Notification"("userId","readAt","createdAt" DESC); CREATE INDEX "Notification_status_lastAttemptAt_idx" ON "Notification"("status","lastAttemptAt");
CREATE INDEX "AlertCheckRun_status_startedAt_idx" ON "AlertCheckRun"("status","startedAt" DESC); CREATE UNIQUE INDEX "EmailOutbox_notificationId_key" ON "EmailOutbox"("notificationId"); CREATE INDEX "EmailOutbox_status_nextAttemptAt_idx" ON "EmailOutbox"("status","nextAttemptAt"); CREATE INDEX "EmailOutbox_userId_idx" ON "EmailOutbox"("userId"); CREATE INDEX "UserConsent_userId_kind_createdAt_idx" ON "UserConsent"("userId","kind","createdAt" DESC); CREATE UNIQUE INDEX "EmailVerificationToken_tokenHash_key" ON "EmailVerificationToken"("tokenHash"); CREATE INDEX "EmailVerificationToken_userId_idx" ON "EmailVerificationToken"("userId"); CREATE INDEX "EmailVerificationToken_expiresAt_idx" ON "EmailVerificationToken"("expiresAt"); CREATE UNIQUE INDEX "PasswordResetToken_tokenHash_key" ON "PasswordResetToken"("tokenHash"); CREATE INDEX "PasswordResetToken_userId_idx" ON "PasswordResetToken"("userId"); CREATE INDEX "PasswordResetToken_expiresAt_idx" ON "PasswordResetToken"("expiresAt");
ALTER TABLE "Account" ADD CONSTRAINT "Account_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "WishlistItem" ADD CONSTRAINT "WishlistItem_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "WishlistItem" ADD CONSTRAINT "WishlistItem_gameId_fkey" FOREIGN KEY ("gameId") REFERENCES "Game"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PriceAlert" ADD CONSTRAINT "PriceAlert_wishlistItemId_fkey" FOREIGN KEY ("wishlistItemId") REFERENCES "WishlistItem"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Notification" ADD CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Notification" ADD CONSTRAINT "Notification_priceAlertId_fkey" FOREIGN KEY ("priceAlertId") REFERENCES "PriceAlert"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "UserConsent" ADD CONSTRAINT "UserConsent_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EmailOutbox" ADD CONSTRAINT "EmailOutbox_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EmailOutbox" ADD CONSTRAINT "EmailOutbox_notificationId_fkey" FOREIGN KEY ("notificationId") REFERENCES "Notification"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EmailVerificationToken" ADD CONSTRAINT "EmailVerificationToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PasswordResetToken" ADD CONSTRAINT "PasswordResetToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
